require_once __DIR__.'/../includes/bootstrap.php';$workspace=require_permission('view');$st=$GLOBALS['pdo']->prepare('SELECT d.*,s.source_type,s.status source_status,s.name source_name,s.last_updated_at FROM datasets d JOIN data_sources s ON s.id=d.source_id WHERE d.workspace_id=? ORDER BY d.created_at DESC');$st->execute([$workspace['id']]);$datasets=$st->fetchAll();require_once __DIR__.'/../includes/header.php';$layout='app';datanix_header('Datasets','datasets',$layout);
?>
<div class="page-head"><div><div class="section-kicker">DATA MANAGEMENT</div><h1>Datasets</h1><p>Semua tabel tersimpan di workspace ini. File upload disimpan di luar web directory.</p></div><div class="page-head-actions"><a class="btn btn-light-outline" href="<?=e(url('datasets/sources.php'))?>">Sources</a><?php if(can('edit_data',$workspace)):?><a class="btn btn-primary" href="<?=e(url('datasets/upload.php'))?>">+ Add dataset</a><?php endif;?></div></div><?php if($datasets):?><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Dataset library</h2><div class="panel-subtitle"><?=e(count($datasets))?> dataset tersedia untuk role Anda.</div></div><input class="form-control form-control-sm" style="max-width:210px" data-filter-table="dataset-table" placeholder="Cari dataset…"></div><div class="table-wrap"><table class="data-table" id="dataset-table"><thead><tr><th>Dataset</th><th>Records</th><th>Fields</th><th>Source</th><th>Last updated</th><th></th></tr></thead><tbody><?php foreach($datasets as $d):?><tr><td><strong><?=e($d['name'])?></strong><?php if($d['is_sample']):?><br><small class="text-subtle">Sample · <?=e($d['source_license'])?></small><?php endif;?></td><td class="mono"><?=e(format_number((int)$d['row_count']))?></td><td class="mono"><?=e(format_number((int)$d['column_count']))?></td><td><span class="badge-soft"><?=e(strtoupper($d['source_type']))?></span> <span class="source-status <?=e($d['source_status'])?>"><?=e($d['source_status'])?></span></td><td><?=e($d['last_updated_at']?date('d M Y H:i',strtotime($d['last_updated_at'])):'—')?></td><td class="d-flex gap-1"><a class="btn btn-light-outline btn-sm" href="<?=e(url('datasets/explorer.php?id='.$d['id']))?>">Explore</a><?php if(can('edit_data',$workspace)):?><form method="post" action="<?=e(url('datasets/delete.php'))?>" data-confirm="Hapus dataset ini? Query, insight, dan widget yang merujuknya akan kehilangan dataset; angka tidak dapat dipulihkan."><?=csrf_field()?><input type="hidden" name="dataset_id" value="<?=e($d['id'])?>"><button class="btn btn-light-outline btn-sm">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php else:?><div class="panel"><div class="panel-body"><div class="empty-state"><div class="empty-icon">▤</div><strong>Belum ada dataset.</strong><p>Mulai dengan mengunggah file atau memuat sampel UCI beratribusi dengan tanggal asli.</p><?php if(can('edit_data',$workspace)):?><a class="btn btn-primary btn-sm" href="<?=e(url('datasets/upload.php'))?>">Unggah dataset</a> <button class="btn btn-light-outline btn-sm" data-sample-load>Impor UCI sample</button><?php endif;?></div></div></div><?php endif;?><div class="source-note mt-3">Dataset mencakup metadata sumber, schema, lisensi/kutipan bila diketahui, jumlah baris, dan tanggal load. User dengan role viewer dapat membaca; edit/delete dibatasi role owner/admin/editor.</div>
